:root {
  --bg-card: #f2ead8;
  --bg-header: #2c3e2d;
  --bg-lens-outer: #d4a843;
  --bg-lens-mid: #b87333;
  --bg-lens-inner: #7a9e7e;
  --bg-lens-core: #2c3e2d;
  --bg-condition: #e0d5bc;
  --bg-condition-fill: #4a7c59;
  --color-header-text: #f2ead8;
  --color-body-text: #3a2e1a;
  --color-label: #7a6a4a;
  --color-value: #2c1f0e;
  --color-tag-bg: #2c3e2d;
  --color-tag-text: #f2ead8;
  --color-section-title: #b87333;
  --color-stamp: #8b1a1a;
  --color-footer-bg: #e6dcc8;
  --color-border: #b8a882;
  --color-cross: #2c3e2d;
  --color-grade: #8b1a1a;
}

article.lens-card {
  width: 480px;
  background: var(--bg-card);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background: var(--bg-header);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
}

.studio-label {
  color: var(--color-header-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
}

.card-number {
  color: var(--color-header-text);
  font-size: 13px;
  font-weight: 400;
  opacity: 0.8;
}

.card-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.lens-preview {
  width: 148px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 16px 12px;
  border-right: 1px solid var(--color-border);
  gap: 8px;
}

.lens-diagram {
  position: relative;
  width: 96px;
  height: 96px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
}

.lens-outer {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: var(--bg-lens-outer);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--color-border);
}

.lens-mid {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--bg-lens-mid);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-border);
}

.lens-inner {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--bg-lens-inner);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-border);
}

.lens-core {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--bg-lens-core);
  border: 1px solid var(--color-border);
}

.lens-cross {
  position: absolute;
  background: var(--color-cross);
  opacity: 0.18;
  border-radius: 1px;
}

.lens-cross--h {
  width: 96px;
  height: 2px;
  top: 50%;
  left: 0;
  transform: translateY(-50%);
}

.lens-cross--v {
  width: 2px;
  height: 96px;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
}

.lens-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--color-body-text);
  letter-spacing: 0.5px;
  text-align: center;
}

.lens-grade {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-grade);
  border: 1px solid var(--color-grade);
  border-radius: 3px;
  padding: 2px 8px;
  letter-spacing: 1px;
}

.lens-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 14px 16px;
  gap: 14px;
}

.detail-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.section-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--color-section-title);
  margin: 0;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 4px;
}

.spec-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.spec-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 12px;
}

.spec-label {
  color: var(--color-label);
  font-weight: 400;
}

.spec-value {
  color: var(--color-value);
  font-weight: 700;
  font-size: 12px;
}

.condition-bar-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.condition-bar {
  flex: 1;
  height: 8px;
  background: var(--bg-condition);
  border-radius: 4px;
  border: 1px solid var(--color-border);
  overflow: hidden;
}

.condition-fill {
  width: 88%;
  height: 100%;
  background: var(--bg-condition-fill);
  border-radius: 4px;
}

.condition-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--bg-condition-fill);
  width: 60px;
}

.tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.tag {
  background: var(--color-tag-bg);
  color: var(--color-tag-text);
  font-size: 10px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 2px;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}

.card-footer {
  background: var(--color-footer-bg);
  border-top: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  padding: 7px 16px;
  gap: 10px;
}

.footer-field {
  font-size: 11px;
  color: var(--color-label);
}

.footer-field strong {
  color: var(--color-body-text);
  font-weight: 700;
}

.footer-divider {
  color: var(--color-border);
  font-size: 12px;
}

.stamp {
  margin-left: auto;
  font-size: 11px;
  font-weight: 700;
  color: var(--color-stamp);
  letter-spacing: 1.5px;
  border: 1px solid var(--color-stamp);
  border-radius: 3px;
  padding: 2px 8px;
}
